Translate("deDE", "thunder-bluff", {
	title = "Thunder Bluff",
	aliases = { "die Stadt Thunder Bluff" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Thunder Bluff ist die {link:capital-city}Hauptstadt{/link} der {link:tauren}Tauren{/link}, errichtet auf einer Gruppe windumtoster Tafelberge, die Hunderte Fuß über die Ebenen von {link:mulgore}Mulgore{/link} aufragen. Brücken aus Holz und Seil schwingen zwischen den Höhen, und jeder Tafelberg ist gekrönt von Zelten, Langhäusern, bemalten Totems und Geisterhütten. Große Aufzüge aus Seil und Holz tragen Reisende vom Gras unten hinauf, und Windreiter kreisen um den mittleren Turm. Es ist eine Stadt vieler Stämme und eine Zuflucht für Jäger, Händler und Handwerker jeder Art. Von seiner Hütte auf dem mittleren Tafelberg aus wacht Hochhäuptling {link:cairne-bloodhoof}Cairne Bloodhoof{/link} über sie alle.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Unzählige Generationen lang hatten die {link:tauren}Tauren{/link} keine Stadt. Sie waren Nomaden, und die {link:centaurs}Zentauren{/link} jagten sie über die Ebenen, bis ihre Stämme wenige und verstreut waren. {link:cairne-bloodhoof}Cairne{/link} von den {link:bloodhoof-village}Bloodhoof{/link} träumte von einem Land, in dem sein Volk in Frieden leben konnte. Mit der Hilfe von {link:thrall}Thrall{/link} und den {link:orcs}Orcs{/link} der {link:horde}Horde{/link} vertrieben die Tauren die Zentauren aus {link:mulgore}Mulgore{/link}. Auf den Tafelbergen an seinem nördlichen Ende erbaute Cairne eine Zuflucht, in der Tauren jedes Stammes willkommen sein sollten. Keine Chronik verzeichnet das Jahr, in dem sie vollendet wurde. Mit der Zeit kamen die verstreuten Stämme zu ihr und vereinten sich unter seiner Herrschaft.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[{link:cairne-bloodhoof}Cairne{/link} ist alt, doch seine Kraft und Weisheit halten die Stämme noch immer zusammen. Nicht jeder Stamm ist mit dem Weg einverstanden, den er gewählt hat. Auf der {link:elder-rise}Anhöhe der Ältesten{/link} hält {link:magatha-grimtotem}Magatha Grimtotem{/link}, die Alte Weise der Grimmtotem, ihren eigenen Rat und ihre eigenen Wachen, und sie glaubt, dass sie, nicht Cairne, die {link:tauren}Tauren{/link} führen sollte. Neben ihr pflegen die Druiden des {link:cenarion-circle}Zirkels des Cenarius{/link} ihre Hütten unter {link:hamuul-runetotem}Erzdruide Hamuul Runetotem{/link}. Abgesandte der {link:forsaken}Verlassenen{/link} wohnen in den Teichen der Visionen und lehren auf der {link:spirit-rise}Anhöhe der Geister{/link}, ein Zeichen des Paktes, der sie in die {link:horde}Horde{/link} brachte. Die Weisen der Stadt sind in der ganzen Horde als Geschichtsschreiber bekannt. In diesen Tagen sind auch neue Gesichter gekommen: Priester von An'she, der Sonne, und Elfen der {link:skyborne}Skyborne{/link}, die auf ihrem Weg vom Lager des {link:earthen-ring}Irdenen Rings{/link} nach {link:orgrimmar}Orgrimmar{/link} hindurchziehen.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die {link:tauren}Tauren{/link} vieler Stämme.{/b} Die {link:bloodhoof-village}Bloodhoof{/link}, die Runetotem, die Wildmane, die Thunderhorn, die Ragetotem, die Stonehoof, die Mistrunner und viele andere gehen auf den Anhöhen ihren Gewerben nach.
• {b}Die Grimmtotem.{/b} {link:magatha-grimtotem}Magatha{/link} und ihre Diener halten eine Ecke der {link:elder-rise}Anhöhe der Ältesten{/link}.
• {b}Die Druiden.{/b} Tauren des Zirkels des {link:cenarius}Cenarius{/link}, angeführt von {link:hamuul-runetotem}Hamuul Runetotem{/link}.
• {b}Die Verlassenen.{/b} Apotheker, Priester und Magier, gesandt aus {link:undercity}Undercity{/link}.
• {b}Reisende der {link:horde}Horde{/link}.{/b} {link:orcs}Orcs{/link}, {link:trolls}Trolle{/link} und nun {link:skyborne}Skyborne{/link} kommen und gehen per Windreiter und Aufzug.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Der lange Marsch.{/b} Thralls {link:orcs}Orcs{/link} geleiteten Cairnes Volk durch das {link:the-barrens}Brachland{/link} nach {link:mulgore}Mulgore{/link}, und {link:cairne-bloodhoof}Cairne{/link} verpflichtete die {link:tauren}Tauren{/link} der {link:horde}Horde{/link}.
• {b}Der Dritte Krieg.{/b} Taurenkrieger kämpften an der Seite der Orcs, der {link:humans}Menschen{/link} und der {link:night-elves}Nachtelfen{/link} in der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link}.
• {b}Die Gründung.{/b} Als die {link:centaurs}Zentauren{/link} vertrieben waren, errichtete Cairne Thunder Bluff und rief die Stämme dorthin.
• {b}Der Pakt mit den Verlassenen.{/b} Als die Verlassenen einen Platz in der Horde suchten, drängten die Ältesten des {link:earthen-ring}Irdenen Rings{/link} darauf, ihnen zu helfen. Cairne stimmte zu, und die Verlassenen kamen als Verbündete nach Thunder Bluff.]=],
		},
		{
			title = "Überlieferungen der Anhöhen",
			text = [=[• Die {link:tauren}Tauren{/link} pflegen den Brauch, von der südlichen Klippe der {link:hunter-rise}Anhöhe der Jäger{/link} aus Weihrauch in die Winde zu streuen.
• Ein junger Taure, der vor den Hochhäuptling tritt, trägt einen Kopfschmuck, und die schönsten werden mit Harpyienfedern aus dem Norden gefertigt.
• Die Weisen von Thunder Bluff haben Metallscheiben erforscht, die aus {link:uldaman}Uldaman{/link} zurückgebracht wurden und deren Glyphen von einem verlorenen Ort namens {link:valley-of-the-watchers}Uldum{/link} sprechen.]=],
		},
	},
})

Translate("deDE", "elder-rise", {
	title = "Die Anhöhe der Ältesten",
	aliases = { "Anhöhe der Ältesten" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Anhöhe der Ältesten ist die nordöstliche Klippe von {link:thunder-bluff}Thunder Bluff{/link}, die Heimat der Weisen der Stadt. Die Druiden des Zirkels des {link:cenarius}Cenarius{/link} haben hier ihre Hütten unter {link:hamuul-runetotem}Erzdruide Hamuul Runetotem{/link}, mit seiner Tochter Bashana, der jungen Druidin {link:nara-wildmane}Nara Wildmane{/link} und den Lehrern der druidischen Künste an ihrer Seite. In einer eigenen Hütte, bewacht von zwei Kriegern ihres Klans, lebt {link:magatha-grimtotem}Magatha Grimtotem{/link}, die Alte Weise. Die beiden Ältesten teilen dieselbe Anhöhe und selten dieselbe Meinung. Wer Rat zu den Nöten des Landes sucht, seien es Geister, Träume oder die Erde selbst, wird hierher geschickt.]=],
		},
	},
})

Translate("deDE", "spirit-rise", {
	title = "Die Anhöhe der Geister",
	aliases = { "Anhöhe der Geister" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Anhöhe der Geister ist die westliche Klippe von {link:thunder-bluff}Thunder Bluff{/link}, wo die Schamanen der Familie Skychaser die Jungen lehren, mit den Geistern der {link:elements}Elemente{/link} zu sprechen. Sie ist auch die Anhöhe der Fremden. Priester und Magier der {link:forsaken}Verlassenen{/link} lehren nun hier, und ein verborgener Pfad windet sich von der Anhöhe hinab in die Höhle der {link:the-pools-of-vision}Teiche der Visionen{/link}, wo die Apotheker aus {link:undercity}Undercity{/link} ihrer Arbeit nachgehen. In diesen Tagen ist auch ein Lehrer der Paladine auf die Anhöhe gekommen. Für viele {link:tauren}Tauren{/link} ist die Anhöhe der Geister der Ort, an dem sie zum ersten Mal den Toten begegnen, die nun ihre Verbündeten sind.]=],
		},
	},
})

Translate("deDE", "hunter-rise", {
	title = "Die Anhöhe der Jäger",
	aliases = { "Anhöhe der Jäger" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Anhöhe der Jäger ist die südliche Klippe von {link:thunder-bluff}Thunder Bluff{/link}, die Anhöhe derer, die von der Jagd und vom Speer leben. Die Jäger der Familie Thunderhorn lehren die Jungen zu spüren und zu zähmen, und die Krieger der Ragetotem lehren sie zu kämpfen. Der große Jäger {link:melor-stonehoof}Melor Stonehoof{/link} schickt von hier aus seine härtesten Jagden aus, gegen Bestien, die außerhalb des Segens der Erdenmutter leben. Von der südlichen Klippe der Anhöhe streuen die {link:tauren}Tauren{/link} Weihrauch in die Winde, wie es ihre Tradition verlangt, und blicken über ganz {link:mulgore}Mulgore{/link}.]=],
		},
	},
})

Translate("deDE", "the-pools-of-vision", {
	title = "Die Teiche der Visionen",
	aliases = { "Teiche der Visionen" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Teiche der Visionen liegen in einer Höhle unter der {link:spirit-rise}Anhöhe der Geister{/link}, erreichbar über einen verborgenen Pfad. Stilles Wasser füllt die Kaverne, und die {link:tauren}Tauren{/link} halten es für heilig. In diesen Tagen sind die Teiche zur Heimat der Abgesandten der {link:forsaken}Verlassenen{/link} in {link:thunder-bluff}Thunder Bluff{/link} geworden. {link:apothecary-zamah}Apothekerin Zamah{/link} von der {link:royal-apothecary-society}Königlichen Apothekervereinigung{/link} arbeitet hier, empfängt seltsame Lieferungen und schickt andere hinaus. An sie wandte sich {link:magatha-grimtotem}Magatha Grimtotem{/link}, als sie ein Heilmittel für die Krankheit des {link:stonetalon-mountains}Steinkrallengebirges{/link} suchte, und das Heilmittel, das die Verlassenen anboten, war ein Gift.]=],
		},
	},
})

Translate("deDE", "cairne-bloodhoof", {
	title = "Cairne Bloodhoof",
	subtitle = "Hochhäuptling der Tauren",
	found = "Seine Hütte auf dem mittleren Tafelberg von Thunder Bluff",
	hint = [=[Steigt auf den höchsten Tafelberg von Thunder Bluff und bittet um eine Audienz beim Hochhäuptling.]=],
	allegiance = "Tauren · Stamm der Bloodhoof · Horde",
	aliases = { "Cairne", "Hochhäuptling Cairne Bloodhoof" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Cairne Bloodhoof ist der Hochhäuptling der {link:tauren}Tauren{/link} und der Gründer von {link:thunder-bluff}Thunder Bluff{/link}. Einst war er der Häuptling eines einzigen Stammes, der {link:bloodhoof-village}Bloodhoof{/link}, die die Ebenen nahe dem großen Meer durchwanderten und in Furcht vor den {link:centaurs}Zentauren{/link} lebten. Nun ist er der Herr aller Taurenstämme und eine der großen Säulen der {link:horde}Horde{/link}. Das Alter hat ihn verlangsamt, aber nicht gebeugt. Er ist ein Krieger ohnegleichen, ein geduldiger Richter und ein Freund derer, die das Land ehren.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Cairne gab seinem Volk eine Heimat. Sein Bündnis mit {link:thrall}Thrall{/link} rettete die {link:tauren}Tauren{/link} vor den {link:centaurs}Zentauren{/link}, und sein Wort band sie an die {link:horde}Horde{/link}. Durch ihn gewann die Horde mehr als Krieger: Sie gewann ein Volk von tiefer Weisheit und altem Glauben. In diesen Tagen hält der Hochhäuptling die Stämme noch immer zusammen, auch wenn nicht alle mit dem Weg einverstanden sind, den er sie führt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er traf {link:thrall}Thrall{/link} auf den Ebenen Kalimdors und wies ihm den Weg zum Orakel des Steinkrallengipfels.
• Er führte sein Volk unter dem Schutz der {link:orcs}Orcs{/link} durch das {link:the-barrens}Brachland{/link} nach {link:mulgore}Mulgore{/link}.
• Er verpflichtete die {link:tauren}Tauren{/link} der {link:horde}Horde{/link} und kämpfte in der {link:battle-of-mount-hyjal}Schlacht am Berg Hyjal{/link}.
• Er gründete {link:thunder-bluff}Thunder Bluff{/link} und machte Mulgore zu einer Heimat für jeden Stamm.
• Er hieß die {link:forsaken}Verlassenen{/link} in der Horde willkommen.
• Er unterhält seine eigenen Späher, die Longwalker, und vertraut ihnen seine Geheimnisse an.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Die Chroniken dieses Zeitalters sagen wenig über Cairnes Jugend, oder über die Jahre, bevor die {link:centaurs}Zentauren{/link} seinen Stamm an den Rand des Untergangs trieben.]=],
		},
	},
	chapters = {
		{
			title = "Der lange Marsch",
			hint = [=[Vollendet die Riten der Erdenmutter und tretet vor den Hochhäuptling.]=],
			text = [=[Bevor die {link:tauren}Tauren{/link} eine Heimat hatten, jagten die {link:centaurs}Zentauren{/link} Cairnes Volk von einem Lager zum nächsten. Als der junge {link:thrall}Kriegshäuptling Thrall{/link} im Kampf auf sie stieß, sah Cairne in den {link:orcs}Orcs{/link} ein Volk, so wild wie edel. Er erzählte Thrall vom Orakel im Norden. Thrall schwor im Gegenzug, die Karawanen der Tauren durch das {link:the-barrens}Brachland{/link} zu schützen, und die Orcs wehrten Welle um Welle von Zentauren ab, bis die Tauren {link:mulgore}Mulgore{/link} erreichten. Cairne vergaß die Schuld nicht. Er folgte Thrall zum {link:stonetalon-mountains}Steinkrallengebirge{/link}, und von jenem Tag an marschierten die Tauren mit der {link:horde}Horde{/link}.]=],
		},
		{
			title = "Das Horn von Arra'chea",
			hint = [=[Beweist dem Hochhäuptling Euren Wert mit einer Jagd auf den Ebenen unten.]=],
			text = [=[Für Cairne wird ein Platz in {link:thunder-bluff}Thunder Bluff{/link} nicht einmal verdient. Er muss gehalten werden. Jeden jungen {link:tauren}Tauren{/link}, der seine Hütte erreicht, erinnert er daran, dass ihr Volk ein Volk von Jägern ist, und er schickt sie hinab auf die Ebenen, um den großen Kodo Arra'chea aufzuspüren und zu erlegen. Wenn das Horn zurückgebracht wird, schickt er einen Trupp aus, um Haut und Fleisch zu holen, damit nichts von dem Tier verschwendet wird.]=],
		},
		{
			title = "Die Longwalker",
			hint = [=[Bringt dem Hochhäuptling Nachricht von seinem vermissten Späher.]=],
			text = [=[Cairne schickte den Longwalker {link:perith-stormhoof}Perith Stormhoof{/link} aus, um mit den {link:palemane-gnolls}Bleichmähnen{/link}-Gnollen zu sprechen, und die {link:gnolls}Gnolle{/link} nahmen ihn gefangen. Als die Nachricht kam, dass Perith in Sicherheit war, war Cairne erleichtert. Er nannte Perith seinen vertrauenswürdigsten Späher und dessen Auftrag einen von höchster Wichtigkeit, und mehr sagte er nicht darüber, worin dieser Auftrag bestand.]=],
		},
		{
			title = "Die Rückkehr der Galak",
			hint = [=[Vertreibt die Zentauren aus Mulgore und erstattet dem Hochhäuptling Bericht.]=],
			text = [=[Die Nachricht, dass die Galak es gewagt hatten, {link:mulgore}Mulgore{/link} zu überfallen, weckte den Zorn des alten Kriegers. Er hatte die {link:centaurs}Zentauren{/link} an Thralls Seite von diesen Ebenen vertrieben, und er ehrte jene, die sie erneut vertrieben, damit die Zentauren sich an den Schmerz erinnerten, der sie erwartet, wenn sie zurückkehren.]=],
		},
	},
	mentions = {
		{ text = "Reise nach {link:thunder-bluff}Thunder Bluff{/link}" },
		{
			text = [=[Die {link:horde}Horde{/link} erkunden, ein Gast der {link:skyborne}Skyborne{/link} in seiner Hütte]=],
		},
		{
			text = [=[{link:rites-of-the-earthmother}Riten der Erdenmutter{/link}, der letzte der Riten]=],
		},
	},
	bonds = {
		{ id = "baine-bloodhoof", name = "Baine Bloodhoof", note = "sein Sohn" },
		{ id = "thrall", name = "Thrall", note = "sein Freund und Kriegshäuptling" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "ein Freund seit Kindertagen" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "seine Rivalin unter den Ältesten" },
		{ id = "perith-stormhoof", name = "Perith Stormhoof", note = "sein vertrauenswürdigster Späher" },
		{ id = "muln-earthfury", name = "Muln Earthfury", note = "Ältester des Irdenen Rings" },
	},
})

Translate("deDE", "magatha-grimtotem", {
	title = "Magatha Grimtotem",
	subtitle = "Alte Weise der Grimmtotem",
	found = "Ihre Hütte auf der Anhöhe der Ältesten",
	hint = [=[Sucht Rat bei der Alten Weisen, die auf der Anhöhe der Ältesten wohnt.]=],
	allegiance = "Klan der Grimmtotem · Thunder Bluff",
	aliases = { "Magatha", "die Alte Weise" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Magatha Grimtotem ist die Alte Weise der Grimmtotem, eine Schamanin, die viele für die mächtigste der {link:tauren}Tauren{/link} halten, und eine der ältesten ihrer Ältesten. Sie wohnt in einer Hütte auf der {link:elder-rise}Anhöhe der Ältesten{/link}, begleitet von zwei Kriegern ihres Klans und von ihrem Diener Rahauro. Viele kommen zu ihr, um Rat zu suchen, und sie gibt ihn gern. Was sie dafür im Gegenzug will, können nur wenige sagen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Magatha ist die große Rivalin von {link:cairne-bloodhoof}Cairne Bloodhoof{/link}. Fast ihr ganzes Leben lang hat sie nach Macht und Ansehen gestrebt, und sie glaubt, dass allein sie dazu taugt, die {link:tauren}Tauren{/link} zu führen. Die Krieger ihres Klans folgen ihr, und sie träumen davon, die niederen Völker aus {link:kalimdor}Kalimdor{/link} zu vertreiben. Doch sie lebt in der Stadt des Hochhäuptlings, sitzt unter seinen Ältesten und spricht für die {link:forsaken}Verlassenen{/link}, denen sie mehr geholfen hat als jeder andere Taure.]=],
		},
		{
			title = "Taten",
			text = [=[• Schon als Mädchen wurde sie mit den Gaben einer Schamanin gesegnet.
• Durch eine arrangierte Ehe wurde sie zur Matriarchin der Grimmtotem. Viele vermuten, dass sie die Ehe selbst arrangierte. Ihr Gefährte starb bald darauf bei einem Kletterunfall, den niemand vorhergesehen hatte.
• Sie sprach für die Verlassenen, als ihr Pakt mit der {link:horde}Horde{/link} zum ersten Mal vorgeschlagen wurde.
• Sie sucht, so sagt sie, einen Weg für die Verlassenen, ihren Pfad zurück ins Leben zu finden.
• Sie schickte Abgesandte, um mit den {link:troggs}Troggs{/link} im {link:ragefire-chasm}Ragefireabgrund{/link} unter {link:orgrimmar}Orgrimmar{/link} zu verhandeln.]=],
		},
	},
	chapters = {
		{
			title = "Die Krankheit auf dem Land",
			hint = [=[Bringt der Alten Weisen die Not des Steinkrallengebirges vor.]=],
			text = [=[Als sie Kunde von den aufgewühlten Geistern des {link:stonetalon-mountains}Steinkrallengebirges{/link} erhielt, sagte Magatha, das Land könne nicht geheilt werden, solange die Krankheit darauf nicht entfernt sei. Die Krankheit war die {link:venture-company}Venture Co.{/link}. Sie wandte sich an die Verlassenen und sagte, ihr Wissen über Krankheiten werde das Vertrauen zwischen den beiden Völkern stärken. Die Apotheker antworteten mit einem Gift, das sich unter den Goblins wie eine Seuche ausbreiten sollte.]=],
		},
		{
			title = "Die Tafel von Beth'Amara",
			hint = "Bringt der Alten Weisen eine uralte Tafel.",
			text = [=[Aus dem fernen {link:azshara}Azshara{/link} kam eine Tafel, geschickt von einer Agentin namens {link:jediga}Jediga{/link}, die angewiesen worden war, sie Magatha persönlich zu übergeben. Magatha behauptete, sie könne ihr zeigen, wie die {link:tauren}Tauren{/link} den Verlassenen helfen könnten, wieder menschlich zu werden. Sie war mit der Arbeit zufrieden, und sie versprach Jediga ihre Bezahlung.]=],
		},
		{
			title = "Die Schlange der Rache",
			hint = "Antwortet auf die Warnung der Alten Weisen vor Arikara.",
			text = [=[Magatha verzauberte ein Pulver, das {link:arikara}Arikara{/link}, eine Schlange der Rache, aus dem heiligen Feuer des Düsterwolkengipfels in {link:thousand-needles}Tausend Nadeln{/link} herbeirufen sollte. Sie warnte, dass die Schlange vielleicht {link:cairne-bloodhoof}Cairne Bloodhoof{/link} nachstelle, erzürnt, weil sich zu viel von den Überlieferungen der {link:tauren}Tauren{/link} verändert habe. Die Tauren des Freiwindpostens konnten nicht verstehen, warum Arikara den Hochhäuptling jagen sollte. Sie zweifelten nicht an Magatha. Sie sei, sagten sie, ihre mächtigste Schamanin.]=],
		},
		{
			title = "Die Troggs von Ragefire",
			hint = "Bergt die Tasche von Magathas verschollenem Abgesandten.",
			text = [=[Magatha suchte Frieden mit den {link:troggs}Troggs{/link}, die aus den Tiefen unter {link:orgrimmar}Orgrimmar{/link} heraufgekommen waren. Stattdessen töteten sie ihre Diplomaten. Einer ihrer Diener, {link:maur-raincaller}Maur{/link} Grimtotem, starb im {link:ragefire-chasm}Ragefireabgrund{/link}, eine Tasche umklammernd. Magatha wollte sie zurück, und sie erklärte die Troggs zu einer Bedrohung für die ganze {link:horde}Horde{/link}.]=],
		},
	},
	mentions = {
		{ text = "Die Alte Weise" },
		{ text = "Magathas Bezahlung an {link:jediga}Jediga{/link}" },
		{ text = "Heiliges Feuer" },
		{
			text = [=[Die Stärke eines Feindes prüfen, ausgesandt von ihrem Diener Rahauro]=],
		},
		{ text = "Die Suche nach der verlorenen Tasche" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "ihr Rivale" },
		{ id = "apothecary-zamah", name = "Apothekerin Zamah", note = "die Verlassene, der sie vertraut" },
		{ id = "sage-truthseeker", name = "Weiser Truthseeker", note = "misstraut dem Pakt, für den sie eintrat" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "teilt die Anhöhe der Ältesten" },
	},
})

Translate("deDE", "hamuul-runetotem", {
	title = "Hamuul Runetotem",
	subtitle = "Erzdruide von Thunder Bluff",
	found = "Seine Hütte auf der Anhöhe der Ältesten",
	hint = [=[Sucht den ältesten Druiden auf, der seine Hütte auf der Anhöhe der Ältesten hat.]=],
	allegiance = "Zirkel des Cenarius · Tauren",
	aliases = { "Erzdruide Hamuul Runetotem", "Hamuul", "Erzdruide Runetotem" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Erzdruide Hamuul Runetotem ist der erste Taurendruide seit vielen Generationen und der Anführer der Druiden von {link:thunder-bluff}Thunder Bluff{/link}. Die Druiden, die am {link:mount-hyjal}Berg Hyjal{/link} kämpften, bewegten ihn, und nach dem Krieg suchte er {link:malfurion-stormrage}Malfurion Stormrage{/link} auf und bat darum, unterrichtet zu werden. Er ist ein Mitglied des {link:cenarion-circle}Zirkels des Cenarius{/link} und seit Kindertagen ein Freund Cairnes.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Hamuul öffnete den {link:tauren}Tauren{/link} die alten Wege der {link:night-elves}Nachtelfen{/link}. Seinetwegen arbeiten nun Druiden beider Völker Seite an Seite, und seine Hütte auf der {link:elder-rise}Anhöhe der Ältesten{/link} ist der Ort, an den sich die Tauren wenden, wenn das Land selbst erkrankt.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt die Jungen aus, um den Druiden zu helfen, die nach einer seltsamen Macht suchen, die ins {link:the-barrens}Brachland{/link} sickert.
• Er betrat die Traumwelt, um zu erfahren, was das Brachland vergiftet.
• Er rät jungen Druiden, in ihrem Umgang mit dem Zirkel über die Streitigkeiten der Völker hinauszublicken.
• Er erforscht die Erde des {link:un-goro-crater}Un'Goro{/link}-Kraters und das Wachstum des Morrowgrain.]=],
		},
	},
	chapters = {
		{
			title = "Die Druids of the Fang",
			hint = [=[Bringt dem Erzdruiden die verdorbenen Panzer aus dem Brachland.]=],
			text = [=[Die Verderbnis in den Oasen des Brachlands führte zu den {link:wailing-caverns}Höhlen des Wehklagens{/link}. Hamuul betrat das Land der Träume und sah dort einen Kult von Druiden, einst edel, die ihren Weg verloren hatten und nun der Verderbnis dienten. Er war alt, und er konnte nicht lange im Traum bleiben. Die junge {link:nara-wildmane}Nara Wildmane{/link} blieb, als er floh.]=],
		},
		{
			title = "Ein Splitter des Albtraums",
			hint = "Überbringt dem Erzdruiden einen seltsamen Splitter.",
			text = [=[Ein Splitter des {link:emerald-dream}Smaragdgrünen Traums{/link} kam zu ihm von einem Druiden, der nicht darüber sprechen wollte. Hamuul blickte hinein, verstummte und sagte nur, dass die Dinge im Traum nicht so seien, wie die Druiden gedacht hätten. Er riet, dass es nicht klug sei, über solche Dinge zu sprechen.]=],
		},
		{
			title = "Die gereinigten Brunnen",
			hint = [=[Bringt Nachricht von den gereinigten Brunnen Mulgores nach Thunder Bluff.]=],
			text = [=[Als {link:mull-thunderhorn}Mull Thunderhorn{/link} meldete, dass die drei {link:water-wells-of-mulgore}Brunnen von Mulgore{/link} gereinigt worden waren, sagte Hamuul, dass Freude wieder durch die Bäche fließe, denn die Brunnen dienen den Tieren ebenso wie dem Volk.]=],
		},
	},
	mentions = {
		{ text = "Die Oasen des Brachlands" },
		{ text = "{link:nara-wildmane}Nara Wildmane{/link}" },
		{ text = "{link:rabine-saturna}Rabine Saturna{/link}" },
		{ text = "Erde aus {link:un-goro-crater}Un'Goro{/link}" },
		{ text = "Forschung am Morrowgrain" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "ein Freund seit Kindertagen" },
		{ id = "nara-wildmane", name = "Nara Wildmane", note = "eine junge Druidin von feurigem Geist" },
		{ id = "mull-thunderhorn", name = "Mull Thunderhorn", note = "schickte ihm Nachricht von den Brunnen" },
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "sein Lehrer" },
	},
})

Translate("deDE", "sage-truthseeker", {
	title = "Weiser Truthseeker",
	subtitle = "Weiser von Thunder Bluff",
	found = "Die untere Anhöhe von Thunder Bluff",
	hint = [=[Sucht den Weisen, der für die Tauren das verlorene Wissen Azeroths sammelt.]=],
	allegiance = "Thunder Bluff · Die Weisen",
	aliases = { "Truthseeker" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Weise Truthseeker ist einer der Weisen von {link:thunder-bluff}Thunder Bluff{/link}, der Geschichtsschreiber der {link:tauren}Tauren{/link}. Er sammelt alte Bücher, Relikte und Geheimnisse aus aller Welt und erforscht sie für sein Volk. Er würde {link:cairne-bloodhoof}Cairne{/link} sein Leben anvertrauen. Den {link:forsaken}Verlassenen{/link} traut er nicht.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Der Weise spricht für die {link:tauren}Tauren{/link}, die am Pakt mit den Toten zweifeln. Er glaubt, dass der {link:earthen-ring}Irdene Ring{/link} es gut meinte, als er die {link:horde}Horde{/link} drängte, ihnen zu helfen, doch er fragt sich, wer seinem Ältestenrat ins Ohr flüsterte. Er steht auch am Rand eines tieferen Geheimnisses, das bis zu den Schöpfern der Welt zurückreicht.]=],
		},
		{
			title = "Taten",
			text = [=[• Er verlangte das Kompendium der Gefallenen von den Eiferern des {link:scarlet-monastery}Scharlachroten Klosters{/link}.
• Er erforscht die {link:lore-keeper-of-norgannon}Scheiben von Norgannon{/link}, die aus {link:uldaman}Uldaman{/link} zurückgebracht wurden.
• Er und {link:nara-wildmane}Nara Wildmane{/link} folgen den Scheiben in Richtung {link:valley-of-the-watchers}Uldum{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Kompendium der Gefallenen",
			hint = [=[Bringt dem Weisen das Buch, das die scharlachroten Eiferer hüten.]=],
			text = [=[Die Verlassenen haben eine Geschichte voller Täuschung, sagt der Weise, und der Pakt wurde zu schnell geschlossen. Vielleicht hätte {link:cairne-bloodhoof}Cairne{/link} die Warnungen aus {link:orgrimmar}Orgrimmar{/link} beachten sollen. Die Eiferer des Scharlachroten Kreuzzugs sind wahnsinnig, doch sie haben die Untoten erforscht, und Truthseeker wollte wissen, was sie gelernt hatten. Er hatte begonnen, sich zu fragen, ob ihr Buch überhaupt existierte.]=],
		},
		{
			title = "Die Platinscheiben",
			hint = "Bringt dem Weisen ein Relikt aus den Gewölben von Uldaman.",
			text = [=[Aus {link:uldaman}Uldaman{/link} kam eine verkleinerte Abschrift der Platinscheiben von Norgannon. Der Weise spürte in ihnen Geheimnisse, die die Erde seit Zeitaltern fest umschlossen hatte. Er machte sich daran zu lernen, wie sie funktionierten, und versprach, dass sie sich mit der Zeit offenbaren würden.]=],
		},
		{
			title = "Vorzeichen von Uldum",
			hint = "Folgt den übersetzten Glyphen der Scheiben.",
			text = [=[Die Glyphen auf den Scheiben sprachen von einem Ort namens {link:valley-of-the-watchers}Uldum{/link}, den die meisten für einen Mythos halten. Truthseeker brachte die Sache vor {link:nara-wildmane}Nara Wildmane{/link}, die die versiegelten Tore im Tal der Behüter in {link:tanaris}Tanaris{/link} gesehen hatte. Gemeinsam befanden sie, dass die Scheiben und Uldum miteinander verbunden waren.]=],
		},
	},
	mentions = {
		{ text = "Die Platinscheiben" },
		{ text = "Sehen, was geschieht" },
		{ text = "Eine zukünftige Aufgabe" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "dem er sein Leben anvertrauen würde" },
		{ id = "nara-wildmane", name = "Nara Wildmane", note = "teilt seine Erforschung von Uldum" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "Verfechterin des Paktes, dem er misstraut" },
	},
})

Translate("deDE", "nara-wildmane", {
	title = "Nara Wildmane",
	subtitle = "Druidin der Anhöhe der Ältesten",
	found = "Ein Zelt auf der Anhöhe der Ältesten",
	hint = [=[Findet die junge Druidin, die im Traum blieb, als andere flohen.]=],
	allegiance = "Zirkel des Cenarius · Tauren",
	aliases = { "Nara" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Nara Wildmane ist eine junge Druidin der {link:elder-rise}Anhöhe der Ältesten{/link}. {link:hamuul-runetotem}Hamuul Runetotem{/link} nennt ihren Geist feurig. Als der Erzdruide den Traum der {link:wailing-caverns}Höhlen des Wehklagens{/link} nicht länger ertragen konnte, blieb Nara darin und lernte die Gesichter der vier Anführer der Druids of the Fang kennen. Sie ist weit gereist und hat vor den versiegelten Toren von {link:valley-of-the-watchers}Uldum{/link} im Süden gestanden.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Nara ist die nächste Generation der Taurendruiden. Wo Hamuuls Kraft versagt, trägt ihre weiter.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie sucht die Traumedelsteine der vier Anführer der Druids of the Fang.
• Sie hilft dem Weisen {link:sage-truthseeker}Truthseeker{/link} bei seiner Erforschung der Scheiben.]=],
		},
	},
	mentions = {
		{ text = "Nara Wildmane" },
		{ text = "Die Anführer der Druids of the Fang" },
		{ text = "Vorzeichen von {link:valley-of-the-watchers}Uldum{/link}" },
		{ text = "Sehen, was geschieht" },
	},
	bonds = {
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "ihr Ältester" },
		{ id = "sage-truthseeker", name = "Weiser Truthseeker", note = "teilt ihre Erforschung von Uldum" },
	},
})

Translate("deDE", "apothecary-zamah", {
	title = "Apothekerin Zamah",
	subtitle = "Abgesandte der Verlassenen",
	found = "Die Teiche der Visionen",
	hint = [=[Findet die verlassene Apothekerin, die in der Höhle unter der Anhöhe der Geister arbeitet.]=],
	allegiance = "Königliche Apothekervereinigung · Verlassene",
	aliases = { "Zamah" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Apothekerin Zamah ist eine Gelehrte der {link:royal-apothecary-society}Königlichen Apothekervereinigung{/link} und eine Abgesandte der {link:forsaken}Verlassenen{/link} bei den {link:tauren}Tauren{/link}. Sie arbeitet in den Teichen der Visionen unter der {link:spirit-rise}Anhöhe der Geister{/link}. Sie sagt, sie diene der Dunklen Fürstin und dem Fortschritt ihres Volkes, und sie erforscht die Kräuter und Sporen Kalimdors mit großem Interesse.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Zamah ist das Gesicht des Paktes zwischen den {link:tauren}Tauren{/link} und den Toten. {link:magatha-grimtotem}Magatha{/link} vertraut ihr. Viele andere nicht.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie sucht Serpentbloom aus den Tiefen der {link:wailing-caverns}Höhlen des Wehklagens{/link}.
• Sie veranlasste ein Gift gegen die {link:venture-company}Venture Co.{/link} im {link:stonetalon-mountains}Steinkrallengebirge{/link}, hergestellt von einem Kollegen in {link:tarren-mill}Tarrens Mühle{/link}.]=],
		},
	},
	mentions = {
		{ text = "Apothekerin Zamah" },
		{ text = "Serpentbloom" },
		{ text = "Reise nach {link:tarren-mill}Tarrens Mühle{/link}" },
		{ text = "Der Flughafen der Flugmaschinen" },
	},
	bonds = {
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "schickt Suchende zu ihr" },
	},
})

Translate("deDE", "melor-stonehoof", {
	title = "Melor Stonehoof",
	subtitle = "Meister der Jagd",
	found = "Die Anhöhe der Jäger",
	hint = [=[Sucht den großen Jäger, der von der Anhöhe der Jäger aus die härtesten Jagden aussendet.]=],
	allegiance = "Tauren · Anhöhe der Jäger",
	aliases = { "Melor" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Melor Stonehoof ist der große Jäger der {link:hunter-rise}Anhöhe der Jäger{/link}. Er zeigt den Jungen den Pfad des Jägers, und er schickt die Bewährten auf Jagden, die nicht der Nahrung, der Ehre oder der Lehre dienen. Es sind Jagden gegen Bestien, die außerhalb des Segens der Erdenmutter leben: Tyrannen, die Furcht unter sanfteren Geschöpfen verbreiten.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Melor hält die Jagd gerecht. Für ihn zählt der Zweck der Hatz ebenso viel wie die Beute.]=],
		},
		{
			title = "Taten",
			text = [=[• Er schickt junge Jäger ins {link:the-barrens}Brachland{/link}, damit sie von dessen Tieren lernen.
• Er setzt Jagden gegen die Hyäne {link:steelsnap}Steelsnap{/link} und andere tyrannische Bestien an.
• Sein Wort erreicht bewährte Jäger selbst im Brachland, getragen von Boten, die sie aufsuchen.]=],
		},
	},
	mentions = {
		{ text = "Der Weg des Jägers" },
		{ text = "{link:sergra-darkthorn}Sergra Darkthorn{/link}" },
		{ text = "Melor schickt Nachricht" },
		{ text = "{link:steelsnap}Steelsnap{/link}" },
		{ text = "Frostmaw" },
		{ text = "{link:deadmire}Deadmire{/link}" },
	},
	bonds = {
		{ id = "skorn-whitecloud", name = "Skorn Whitecloud", note = "schickt ihm junge Jäger" },
	},
})

Translate("deDE", "eyahn-eagletalon", {
	title = "Eyahn Eagletalon",
	subtitle = "Fertigt zeremoniellen Kopfschmuck",
	found = "Die untere Anhöhe von Thunder Bluff",
	hint = [=[Findet auf der unteren Anhöhe jemanden aus dem Volk der Tauren, der einen zeremoniellen Kopfschmuck fertigt.]=],
	allegiance = "Tauren",
	aliases = { "Eyahn" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Eyahn Eagletalon fertigt einen zeremoniellen Kopfschmuck. Eyahns Bruder wird bald vor den Hochhäuptling treten, und seinen Kopfschmuck anzufertigen ist eine Ehre. Die Lederriemen sind fast gegerbt, doch es bleibt keine Zeit, auch die Federn zu sammeln: sechs azurblaue und sechs bronzene, von einer Größe, die man nur bei den {link:harpies}Harpyien{/link} nördlich und nordwestlich der Stadt findet. Eyahn bittet vorbeiziehende Reisende, die Harpyien dafür zu jagen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Eyahn hält einen der kleinen Bräuche von {link:thunder-bluff}Thunder Bluff{/link} am Leben: dass niemand ungeschmückt vor {link:cairne-bloodhoof}Cairne{/link} tritt.]=],
		},
		{
			title = "Taten",
			text = [=[• Fertigt einen Kopfschmuck für einen Bruder, der bald vor den Hochhäuptling treten wird.
• Gerbt dessen Lederriemen, während andere die Federn sammeln.]=],
		},
	},
	mentions = {
		{ text = "Vorbereitung für die Zeremonie" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "der Häuptling, vor den der Bruder treten wird" },
	},
})

Translate("deDE", "eylah-sunhorn", {
	title = "Eylah Sunhorn",
	subtitle = "Sonnenpriester von An'she",
	found = "Die untere Anhöhe von Thunder Bluff",
	hint = [=[Sucht unter den Priestern der Sonne nach jemandem, der die alte Tradition des Weihrauchs bewahrt.]=],
	allegiance = "Sonnenpriester von An'she · Tauren",
	aliases = { "Eylah" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Eylah Sunhorn gehört zur Priesterschaft von An'she, der Sonne, die die {link:tauren}Tauren{/link} als eines der Augen der Erdenmutter ehren. Eylah grüßt Reisende mit dem Segen von An'she und bewahrt einen alten Brauch der Tauren: Weihrauch in die Winde zu streuen. Der Weihrauch wird aus Kräutern, Zedernholz, Sehnenfaden und zeremoniellem Feuerstein gemacht, und er wird von der südlichen Klippe der {link:hunter-rise}Anhöhe der Jäger{/link} ausgestreut.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Eylah gehört zu den Priestern der Sonne, die in diesen Tagen in {link:thunder-bluff}Thunder Bluff{/link} hervorgetreten sind.]=],
		},
		{
			title = "Taten",
			text = [=[• Bittet Reisende, die Tradition des Weihrauchs zu ehren.
• Schickt sie für die Zutaten zum Kräuterkundigen, zu den Lieferanten der Verzauberer und Lederer und zum Lieferanten des Kochs der Stadt.]=],
		},
	},
	mentions = {
		{ text = "Traditionen der Anhöhen" },
	},
})

Translate("deDE", "grimtotem-clan", {
	title = "Klan der Grimmtotem",
	aliases = { "Grimmtotemklan", "Stamm der Grimmtotem", "die Grimmtotem" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Grimmtotem sind ein Taurenklan, der den anderen nicht gleicht. Wo die meisten {link:tauren}Tauren{/link} Einklang mit dem Land suchen, suchen die Grimmtotem, es zu beherrschen. Sie glauben, dass die niederen Völker aus {link:kalimdor}Kalimdor{/link} vertrieben werden sollten und dass die Tauren die Länder ihrer Ahnen zurücknehmen sollten. Ihre Matriarchin ist {link:magatha-grimtotem}Magatha{/link}, die Alte Weise, und ihre Krieger folgen ihr.]=],
		},
		{
			title = "Der Klan und die Stadt",
			text = [=[{link:magatha-grimtotem}Magatha{/link} lebt auf der {link:elder-rise}Anhöhe der Ältesten{/link} in {link:thunder-bluff}Thunder Bluff{/link}, bewacht von Kriegern ihres Klans, und die Grimmtotem dort genießen die Rechte jedes {link:tauren}Tauren{/link}. Es heißt, {link:cairne-bloodhoof}Cairne{/link} habe ihr einen Platz so nahe bei sich gegeben im Sinne eines alten Sprichworts: Halte deine Freunde nahe und deine Feinde noch näher. Draußen in den wilden Landen ist der Klan eine andere Sache.]=],
		},
		{
			title = "In den wilden Landen",
			text = [=[• {b}{link:thousand-needles}Tausend Nadeln{/link}.{/b} Die Grimmtotem halten den {link:darkcloud-pinnacle}Düsterwolkengipfel{/link}, wo sie ihre Toten neben einem heiligen Feuer begraben. Die {link:tauren}Tauren{/link} des Freiwindpostens beobachten sie genau. Man hat Agenten unbekannter Herkunft gesehen, die sie besuchten, und ein Verstoßener des Klans, {link:arnak-grimtotem}Arnak{/link}, wird wegen Mordes und Entführung gesucht.
• {b}Das {link:stonetalon-mountains}Steinkrallengebirge{/link}.{/b} Plünderer der Grimmtotem fielen über ein Taurendorf nahe den Bergen her und töteten fast jeden darin.
• {b}Der Irdene Ring.{/b} Nicht jeder Grimmtotem geht den Weg des Klans. In diesen Tagen dient ein Schamane namens Yorn Grimtotem beim Irdenen Ring in {link:mulgore}Mulgore{/link}.]=],
		},
	},
})
